 1  import { Grid, Paper, Typography } from '@mui/material';
 2  import { alpha, Theme } from '@mui/material/styles';
 3  
 4  import makeStyles from '@mui/styles/makeStyles';
 5  
 6  const useStyles = makeStyles((theme: Theme) => ({
 7    root: {
 8      padding: theme.spacing(2),
 9    },
10    card: {
11      padding: theme.spacing(2),
12      marginTop: theme.spacing(1) * 3,
13      backgroundColor: alpha(theme.palette.primary.main, 0.06),
14    },
15    title: {
16      marginBottom: theme.spacing(1),
17      minHeight: titleMinHeight(theme),
18    },
19  }));
20  
21  // Shared with UsersTable so card titles and the table header line up.
22  export const titleMinHeight = (theme: Theme): number => parseInt(theme.spacing(4), 10) + 24;
23  
24  export interface Kpi {
25    label: string;
26    value: string;
27    trend: 'up' | 'down' | 'flat';
28  }
29  
30  const KPIS: Kpi[] = [
31    { label: 'Active users', value: '1,284', trend: 'up' },
32    { label: 'Open tickets', value: '37', trend: 'down' },
33    { label: 'Uptime', value: '99.95%', trend: 'flat' },
34  ];
35  
36  const TREND_TEXT: Record<Kpi['trend'], string> = {
37    up: 'Up on last week',
38    down: 'Down on last week',
39    flat: 'Same as last week',
40  };
41  
42  export function Dashboard({ kpis = KPIS }: { kpis?: Kpi[] }) {
43    const classes = useStyles();
44    return (
45      <section className={classes.root} aria-labelledby="dashboard-title">
46        <Grid container justifyContent="space-between" alignItems="center">
47          <Typography id="dashboard-title" variant="h4" component="h1">
48            Dashboard
49          </Typography>
50          <Typography variant="body2" color="textSecondary">
51            Last 7 days
52          </Typography>
53        </Grid>
54        <Grid container spacing={2}>
55          {kpis.map((kpi) => (
56            <Grid item xs={12} md={4} key={kpi.label}>
57              <Paper className={classes.card} component="article" aria-label={kpi.label}>
58                <Typography variant="subtitle2" component="h2" className={classes.title}>
59                  {kpi.label}
60                </Typography>
61                <Typography variant="h5">{kpi.value}</Typography>
62                <Typography variant="caption">{TREND_TEXT[kpi.trend]}</Typography>
63              </Paper>
64            </Grid>
65          ))}
66        </Grid>
67      </section>
68    );
69  }
